```js
function memoize(fn) {
  const cache = {};
  return function(...args) {
    const key = JSON.stringify(args);
    if (key in cache) return cache[key];
    const res = fn.apply(this, args);
    cache[key] = res;
    return res;
  };
}
```

```js
function once(fn) {
  let ran = false, res;
  return function(...args) {
    if (!ran) {
      ran = true;
      res = fn.apply(this, args);
    }
    return res;
  };
}
```

